mapper.sql:
WHERE (h.target_user_id = #{query.userId}
       OR h.affected_user_ids LIKE CONCAT('%,', #{query.userId}, ',%'))
AND h.occurred_time >= #{query.startTime}
AND h.occurred_time <= #{query.endTime}

WHERE l.resource_id = #{query.resourceId}
  AND l.action_code IN

      #{actionCode}

AND l.create_time >= #{query.startTime}
AND l.create_time <= #{query.endTime}

WHERE event.user_id = #{query.userId}
  AND event.action IN

      #{action}

AND event.occurred_time >= #{query.startTime}
AND event.occurred_time <= #{query.endTime}

mapper.select:
SELECT COUNT(*) FROM ( SELECT h.id FROM t_authorization_history h
AND #{query.filterSource} = 'AUTHORIZATION_HISTORY' AND h.subject_type = #{query.filterSubjectType} AND h.change_type = #{query.filterChangeType}
UNION ALL SELECT l.id FROM t_operation_log l
AND #{query.filterSource} = 'OPERATION_LOG' AND l.action_code = #{query.filterActionCode}
UNION ALL SELECT event.id FROM t_user_lifecycle_event event
AND #{query.filterSource} = 'USER_LIFECYCLE_EVENT' AND event.action = #{query.filterActionCode}
) history_count

SELECT history_rows.* FROM ( SELECT h.id, 'AUTHORIZATION_HISTORY' AS source_key, h.subject_type, h.subject_id, h.change_type, h.target_user_id, h.role_id, h.permission_id, h.effect, h.data_scope_code, h.effective_from, h.effective_to, h.before_value, h.after_value, h.reason, h.operator_id, COALESCE(NULLIF((SELECT MAX(log_entry.user_name) FROM t_operation_log log_entry WHERE log_entry.request_id = h.request_id), ''), '系统') AS operator_name, NULL AS operator_employee_no, NULL AS action_code, 'SUCCESS' AS result, NULL AS detail, h.occurred_time FROM t_authorization_history h
AND #{query.filterSource} = 'AUTHORIZATION_HISTORY' AND h.subject_type = #{query.filterSubjectType} AND h.change_type = #{query.filterChangeType}
UNION ALL SELECT l.id, 'OPERATION_LOG', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, l.user_id, COALESCE(NULLIF(l.user_name, ''), '系统'), NULL, l.action_code, l.result, l.detail, l.create_time FROM t_operation_log l
AND #{query.filterSource} = 'OPERATION_LOG' AND l.action_code = #{query.filterActionCode}
UNION ALL SELECT event.id, 'USER_LIFECYCLE_EVENT', NULL, NULL, NULL, event.user_id, NULL, NULL, NULL, NULL, NULL, NULL, event.before_value, event.after_value, event.reason, event.operator_id, COALESCE(NULLIF((SELECT MAX(log_entry.user_name) FROM t_operation_log log_entry WHERE log_entry.request_id = event.request_id), ''), '系统'), NULL, CONCAT('USER_', event.action), 'SUCCESS', NULL, event.occurred_time FROM t_user_lifecycle_event event
AND #{query.filterSource} = 'USER_LIFECYCLE_EVENT' AND event.action = #{query.filterActionCode}
) history_rows ORDER BY history_rows.occurred_time DESC, history_rows.source_key ASC, history_rows.id DESC LIMIT #{query.offset}, #{query.limit}
